"use strict";(globalThis.webpackChunkgrc||=[]).push([[59851],{77086(e){e.exports=JSON.parse('{"citeKey":"sun2005scalabilityheterogeneous","slug":"sun-2005-scalability-heterogeneous-6339","title":"Scalability of Heterogeneous Computing","authors":["X.-H. Sun","Y. Chen","M. Wu"],"venue":"The 34rd International Conference on Parallel Processing, Oslo, Norway","type":"Conference","entryType":"inproceedings","date":"June, 2005","year":2005,"era":"iit","month":6,"doi":"10.1109/icpp.2005.69","abstract":"Scalability is a key factor of the design of distributed systems and parallel algorithms and machines. However, conventional scalabilities are designed for homogeneous parallel processing. There is no suitable and commonly accepted definition of scalability metric for heterogeneous systems. Isospeed scalability is a well-defined metric for homogeneous computing. This study extends the isospeed scalability metric to general heterogeneous computing systems. The proposed isospeed-efficiency metric is suitable for both homogeneous and heterogeneous computing. Through theoretical analysis, we derive methodologies of scalability measurement and prediction for heterogeneous systems. Experimental results verify the analytical results and confirm that the proposed isospeed-efficiency scalability works well in both homogeneous and heterogeneous environments.","hasAbstract":true,"lede":"The proposed isospeed-efficiency metric is suitable for both homogeneous and heterogeneous computing.","links":{"pdf":"https://grc.iit.edu/papers/2005/sun-2005-scalability-heterogeneous-6339.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);